#!/bin/bash
# rebase_urgent.sh — Create Jules sessions for rebasing conflicting PRs
# Generated by triage on 2026-07-28
# Usage: bash rebase_urgent.sh [--dry-run]

set -euo pipefail

DRY_RUN="${1:---no-dry-run}"
SESSIONS_FILE="/home/masum/github/remote/jules/jules_sessions.json"

create_jules_session() {
    local pr_number="$1"
    local title="$2"
    local branch="$3"
    local base="$4"
    local priority="$5"

    echo "========================================"
    echo "SESSION for PR #${pr_number}: ${title}"
    echo "  branch: ${branch} → rebase onto ${base}"
    echo "  priority: ${priority}"
    echo "========================================"

    if [ "$DRY_RUN" = "--dry-run" ]; then
        echo "[DRY-RUN] Would create Jules session for PR #${pr_number}"
        return 0
    fi

    # Create session entry in jules_sessions.json
    local session_entry
    session_entry=$(cat <<EOF
{
  "pr": ${pr_number},
  "title": "${title}",
  "branch": "${branch}",
  "base": "${base}",
  "priority": "${priority}",
  "action": "rebase",
  "created": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "instructions": "Rebase branch '${branch}' onto latest '${base}' and resolve conflicts. Ensure tests pass and push the rebased branch."
}
EOF
)

    # Append to sessions file (create if not exists)
    if [ ! -f "$SESSIONS_FILE" ]; then
        echo "[]" > "$SESSIONS_FILE"
    fi

    # Use python to safely append JSON
    python3 -c "
import json
with open('${SESSIONS_FILE}', 'r') as f:
    sessions = json.load(f)
sessions.append(json.loads('''${session_entry}'''))
with open('${SESSIONS_FILE}', 'w') as f:
    json.dump(sessions, f, indent=2)
"

    echo "  → Session appended to ${SESSIONS_FILE}"
}

